    private byte[] activeNameBuffer(int program, int lengthParameter) {
        int[] maxLength = new int[1];
        nglGetProgramiv(program, lengthParameter, Address.ofData(maxLength));
        int capacity = maxLength[0];
        if (capacity < 1) capacity = 256;
        if (capacity > 4096) capacity = 4096;
        return new byte[capacity];
    }

    private static int checkedLength(int length, int capacity) {
        if (length < 0) return 0;
        return length > capacity ? capacity : length;
    }

    private static int activeNameLength(byte[] name, int reportedLength) {
        if (reportedLength >= 0 && reportedLength <= name.length) return reportedLength;
        int length = 0;
        while (length < name.length && name[length] != 0) length++;
        return length;
    }

